import assert from "node:assert/strict"
import { spawnSync } from "node:child_process"
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { dirname, join, relative } from "node:path"
import { test } from "node:test"
import { fileURLToPath, pathToFileURL } from "node:url"
import fc from "fast-check"
import { sourceOfEmitted } from "../emitted-js.mjs"

const preload = fileURLToPath(new URL("../bun.mjs", import.meta.url))
const corpus = JSON.parse(readFileSync(new URL("./corpus/opencode-stale-emitted-receipt.json", import.meta.url), "utf8"))

function witness({ name, extension, receipt, sibling, shebang }) {
  const root = realpathSync(mkdtempSync(join(tmpdir(), "vibelang-emitted-fallback-")))
  const put = (name, text) => {
    const path = join(root, name)
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, text)
    return path
  }
  try {
    put("package.json", JSON.stringify({ type: "module" }))
    const source = "src/" + name + ".ts"
    const output = ".vibelang/js/src/" + name + "." + extension
    const path = put(output, "")
    const map = JSON.stringify({ version: 3, sources: [relative(dirname(path), join(root, source))], names: [], mappings: "" })
    const code = "export const value = 1; export const token = {}; export let count = 0; export function bump() { count++ }\n"
    const header = "// Generated by vibelang from " + source + "; the migrate flow writes it again with each batch.\n"
    const metadata = receipt === "header" ? "" : "//# sourceMappingURL=" + (receipt === "inline"
      ? "data:application/json;base64," + Buffer.from(map).toString("base64")
      : "value.map") + "\n"
    put(output, (shebang ? "#!/usr/bin/env node\n" : "") + header + code + metadata)
    if (receipt === "external") put(relative(root, join(dirname(path), "value.map")), map)
    // A migrated sibling must not steal an output whose receipt names the
    // removed TypeScript source. Artifact-only packages have no sibling.
    if (sibling) put("src/" + name + ".vibe", "export const value = 99\n")
    assert.equal(sourceOfEmitted(path), undefined)
    put("probe.mjs", "const a = await import(process.argv[2]); const b = await import(process.argv[2]); a.bump(); console.log(JSON.stringify({value:a.value,same:a.token===b.token,count:b.count,keys:Object.keys(a).sort()}))\n")
    const run = (command, args) => {
      const result = spawnSync(command, [...args, command === process.execPath ? pathToFileURL(path).href : path], {
        cwd: root, encoding: "utf8", timeout: 10000,
        env: { ...process.env, VIBELANG_PROJECT: "", VIBELANG_CACHE_DIR: join(root, ".cache") }
      })
      assert.equal(result.status, 0, result.stderr)
      return JSON.parse(result.stdout)
    }
    const expected = { value: 1, same: true, count: 1, keys: ["bump", "count", "token", "value"] }
    assert.deepEqual(run(process.execPath, ["probe.mjs"]), expected)
    assert.deepEqual(run("bun", ["--preload", preload, "probe.mjs"]), expected)
  } finally { rmSync(root, { recursive: true, force: true }) }
}

test("Bun loads the committed artifact after its TypeScript source migrated", () => witness(corpus))
test("Bun preserves emitted modules with missing receipt sources across artifact layouts", () => {
  fc.assert(fc.property(fc.record({
    name: fc.constantFrom("value", "with space", "hash#name", "percent%name", "unicode-é", "deep/value"),
    extension: fc.constantFrom("js", "mjs"),
    receipt: fc.constantFrom("header", "inline", "external"),
    sibling: fc.boolean(), shebang: fc.boolean()
  }), witness), { seed: 20261108, numRuns: 48 })
})
